// Asks kimi-k3 (a different model family from the Haiku that wrote S02) for time phrases
// covering the families in PLAN §8. Output: phrases-llm.tsv (family<TAB>phrase). Committed,
// because LLM output can't be regenerated byte-identically.
// Usage: node gen-phrases.mjs
import { writeFileSync } from "node:fs"
import { chat, model } from "./llm.mjs"

const batches = [
  {
    families: {
      relative: "today, yesterday, tomorrow, this/last/past/previous N hours/days/weeks/months/quarters/years, N days ago, a week ago",
      recent: "recent, recently, lately, newest stuff in the last little while",
      "time-of-day": "this morning, last night, yesterday afternoon, yesterday 2am, today at 3pm, tonight",
    },
    n: 50,
  },
  {
    families: {
      weekday: "on monday, last friday, this wednesday, next tue, tuesday's, mon",
      month: "in march, march 2025, last march, dec, sept 2024, this month",
      quarter: "q3, q2 2025, last quarter, this quarter, Q1 FY26",
      year: "2025, in 2024, last year, this year",
    },
    n: 50,
  },
  {
    families: {
      absolute: "3 oct, oct 3, 3/10, 3/10/26, 2026-10-03, 3rd october, october 3rd 2025, the 15th",
      "operator-single": "before X, after X, since X, until X, by X, on X, from X, older than X, newer than X, within the last X",
    },
    n: 50,
  },
  {
    families: {
      "operator-range": "between X and Y, from X to Y, X - Y, X through Y, between the 1st and 15th",
      anchor: "phrases that refer to a team's own periods or events: this sprint, last sprint, before the offsite, since release 4.2.1, after the launch, before diwali, during the all-hands",
      messy: "any family above, but typed sloppily: typos, no spaces, ALL CAPS, abbreviations (yday, lst wk, 2wks), possessives, Hinglish (kal, parso, pichle hafte)",
    },
    n: 50,
  },
]

const lines = []
for (const [i, b] of batches.entries()) {
  const families = Object.entries(b.families)
    .map(([k, v]) => `- ${k}: e.g. ${v}`)
    .join("\n")
  const prompt = `You are helping build a test set for a search box. People type short time constraints into search boxes for chat, email, files and issue trackers, e.g. "pdfs from rahul last week" — here the time phrase is "last week".

Write ${b.n} distinct time phrases, ONLY the time phrase itself (no other words of the query), spread across these families:
${families}

Make them realistic and varied: mostly lowercase, terse, the way people actually type. Vary numbers, units, weekdays and months. Don't repeat the examples verbatim more than a couple of times.

Output exactly ${b.n} lines, each "family<TAB>phrase", using the family names above. No numbering, no commentary.`
  const out = await chat(prompt, { temperature: 1 })
  const got = out
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l.includes("\t"))
  console.error(`batch ${i}: ${got.length} lines`)
  lines.push(...got)
}

const seen = new Set()
const unique = lines.filter((l) => {
  const p = l.split("\t")[1].trim().toLowerCase()
  if (seen.has(p)) return false
  seen.add(p)
  return true
})
writeFileSync(
  new URL("phrases-llm.tsv", import.meta.url),
  `# written by ${model}, ${new Date().toISOString().slice(0, 10)}; see gen-phrases.mjs\n# family\tphrase\n${unique.join("\n")}\n`,
)
console.error(`${unique.length} unique phrases`)
